class MatrixNamedFragmentsTests(unittest.TestCase):
    """Keep permission local to exact physical Element fragments."""

    def test_exact_role_inventory_has_element_policy_and_original_counts(self) -> None:
        """Join every opted-in role through the canonical normalizer."""
        actual = []
        for filename in ("warp_level_matrix_multiply_accumulate.yaml",
                         "asynchronous_warpgroup_matrix_multiply_accumulate.yaml"):
            for instruction in normalize_instruction_spec(load_yaml(packaged_spec_dir() / filename)):
                for variant in instruction.variants:
                    for layout in variant.operand_layouts:
                        for operand in layout.operands:
                            if not operand.vector_allow_named:
                                continue
                            self.assertIs(operand.vector_type_policy, OperandVectorTypePolicy.ELEMENT)
                            self.assertTrue(operand_syntax_shapes(operand) & OperandSyntaxShape.IDENTIFIER_REF)
                            fragment = next(f for f in variant.matrix.fragments if f.operand == operand.name)
                            actual.append((instruction.opcode, variant.name, layout.name, operand.name,
                                           fragment.register_count, fragment.register_type))
                            if operand.kind is OperandKind.MATRIX_FRAGMENT:
                                self.assertEqual(operand.vector_arities, ())
                                self.assertIsNone(operand.vector_arity_expression)
                                self.assertEqual((operand.minimum_elements, operand.maximum_elements),
                                                 (fragment.register_count, fragment.register_count))
        self.assertCountEqual(actual, EXPECTED)

    def test_matrix_optin_consumes_cardinality_without_duplicate_arity(self) -> None:
        """Reject alternate policy, extra options and unsupported counts before IR."""
        for count in (2, 4):
            raw = {"name": "a", "kind": "matrix_fragment", "type": "b32",
                   "cardinality": {"min": count, "max": count}, "element_kinds": ["reg"],
                   "vector": {"allow_named": True, "type_policy": "element"}}
            operand = normalize_operand(deepcopy(raw))
            self.assertTrue(operand.vector_allow_named)
            self.assertEqual(operand.vector_arities, ())
            for change in ({"arity": count}, {"allow_sink": False},
                           {"type_policy": "aggregate"}, {"allow_named": False}):
                bad = deepcopy(raw)
                bad["vector"].update(change)
                with self.subTest(change=change), self.assertRaises(ValueError):
                    normalize_operand(bad)
        for count in (1, 8, 128):
            bad = deepcopy(raw)
            bad["cardinality"] = {"min": count, "max": count}
            with self.subTest(count=count), self.assertRaises(ValueError):
                normalize_operand(bad)
